export function createGateway(env) {
  const channel = slack({
    botToken: env.SLACK_BOT_TOKEN,
    webhook: { signingSecret: env.SLACK_SIGNING_SECRET, path: '/webhooks/slack' },
    // Each Slack user (scoped to their workspace) is their own participant and,
    // by default, gets a Chat instance of their own.
    participant: (event) => (event.actor ? { id: event.actor.id, name: event.actor.username } : null),
  });
  channel.deliver ??= slackDeliver(env.SLACK_BOT_TOKEN);

  return new ChannelGateway({
    channels: { slack: channel },
    agent(route) {
      const stub = () => getAgentByName(env.Chat, route);
      return {
        receive: async (event, origin) => (await stub()).receive(event, origin),
        fetch: async (request) => (await stub()).fetch(request),
      };
    },
  });
}

